export function massBudget({width,depth,thickness,density,mass,height,plateHeight,target,ballastHeight}){const plate=width*depth*thickness/1000*density,total=mass+plate,com=(mass*height+plate*plateHeight)/total,den=target-ballastHeight;const ballast=Math.abs(den)<1e-9?NaN:total*(com-target)/den;return {plate,total,com,ballast:ballast>=0?ballast:NaN};}
export function plateSTL(w,d,h){const v=[[0,0,0],[w,0,0],[w,d,0],[0,d,0],[0,0,h],[w,0,h],[w,d,h],[0,d,h]],faces=[[0,2,1],[0,3,2],[4,5,6],[4,6,7],[0,1,5],[0,5,4],[1,2,6],[1,6,5],[2,3,7],[2,7,6],[3,0,4],[3,4,7]];return 'solid sentinel_plate_mm\n'+faces.map(f=>'facet normal 0 0 0\nouter loop\n'+f.map(i=>'vertex '+v[i].join(' ')).join('\n')+'\nendloop\nendfacet').join('\n')+'\nendsolid sentinel_plate_mm';}
